toad_implementation.code_blueprint:
canvas {
  size: 800px 960px;
  fill: #FFFFFF;
  font-family: "Merriweather, serif";
}

>navy = #1E293B;
>gold = #C5A059;
>muted = #64748B;
>lineColor = #E2E8F0;

text #kicker {
  at: top left of canvas offset 56px 56px;
  content: "FINANCIAL REPORT // FISCAL YEAR 2025";
  font-size: 11px;
  font-weight: 700;
  color: >gold;
}

text #mainHeadline {
  at: below #kicker offset 14px;
  size: 680px;
  content: "Sustained Capital Growth & Resilience";
  font-size: 34px;
  font-weight: 300;
  color: >navy;
}

rect #headerDivider {
  at: below #mainHeadline offset 24px;
  size: 688px 1px;
  fill: >gold;
}

rect #row1 {
  at: below #headerDivider offset 32px;
  size: 688px 48px;
  fill: #F8FAFC;
}

text #row1Title {
  at: left center of #row1 offset 16px 0px;
  content: "Consolidated Group Revenue";
  font-size: 14px;
  font-weight: 700;
  color: >navy;
}

text #row1Val {
  at: right center of #row1 offset -16px 0px;
  content: "€ 1,842.6 M";
  font-size: 15px;
  font-weight: 700;
  color: >navy;
}

rect #row2 {
  at: below #row1 offset 8px;
  size: 688px 48px;
  fill: #FFFFFF;
  stroke: >lineColor;
  stroke-width: 1px;
}

text #row2Title {
  at: left center of #row2 offset 16px 0px;
  content: "Operating Profit (EBITDA)";
  font-size: 14px;
  color: >navy;
}

text #row2Val {
  at: right center of #row2 offset -16px 0px;
  content: "€ 412.0 M";
  font-size: 15px;
  font-weight: 700;
  color: >gold;
}
